# WAR ARENA - Account Profile (read-only aggregation) - Installer
# Aggregates balance + free quota + tier + active monitors for display.
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-account.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - Account Profile installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/product/account/accountProfile.ts" ""
Write-B64 "tests/unit/accountProfile.test.ts" ""

Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
Write-Host ""; Write-Host "Installed. Expected: 904 passed + 1 skipped, 427 guards." -ForegroundColor Green
